ons: DRIVE/SPOT_UP/TRANSITION=5; others 0 (PNR/CUT/POST_UP/PUTBACK). SPOT_UP lag-1 lift +0.027 ctrl_p=0.0000. Within-team: all horizons 0 except SPOT_UP horizon(all)=1; PNR lag-1 within_team_lift=-0.0218.", "auto_failure_mechanism": "C_artifact (apparent effect produced by a construction, selection or labelling flaw)", "observed_failure_evidence": "Flat non-decaying global lifts disappear after team-season demeaning; remaining within-team memory is essentially none except SPOT_UP lag-1.", "observed_sample_and_power": "DRIVE lag-1 n=163696; SPOT_UP n=175021", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF-APPS-059"}]}, {"id": "FAM:SF-APPM-011", "label": "Study family SF-APPM-011: Net-swing play-type scoring prototype", "score": 0.27, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPM-011 (0.21)", "request matches VAR:PPP_points_per_possession (0.40); FAM:SF-APPM-011 auto_measures VAR:PPP_points_per_possession"], "attributes": {"observed_research_question": "Net-swing play-type scoring prototype", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "Scoring PTs by own PPP minus opponent next-possession PPP changes recommendations.", "observed_result": "Top recommendation changes in 40/104 = 38% units; DRIVE median net swing -0.27 (negative 88%), POST_UP -0.22 (77%).", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "Not evaluated against outcomes; uses in-series observed opp_next_PPP.", "observed_sample_and_power": "NOT_RECORDED", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_method": "52 playoff series / 104 team-offense units; compare rank orderings own-PPP vs net-swing.", "observed_verdict": "descriptive", "observed_failure_type": "E_unclear", "observed_notes": "NOT_RECORDED", "auto_confidence": "medium (0.65)"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF-APPS-049"}, {"rel": "auto_addresses_question", "node": "RQC:RQC-005"}]}, {"id": "FAM:SF-APPS-049", "label": "Study family SF-APPS-049: 52-series sequential adaptation: durable pivot branches and net swing", "score": 0.27, "reached_via": ["FAM:SF-APPM-011 auto_related_family (repeat_order_unknown) FAM:SF-APPS-049", "FAM:SF-APPM-011 auto_related_family (repeat_order_unknown) FAM:SF-APPS-049"], "attributes": {"observed_research_question": "52-series sequential adaptation: durable pivot branches and net swing", "auto_outcome_status": "rejected", "observed_hypothesis": "If-X-fails-then-Y pivot branches and PT net-swing (own PPP - opp next PPP) are durable across ~104 playoff team-offense units.", "observed_result": "durable_branches=[]. Median net swing: CUT +0.36 (neg in 9%), TRANSITION +0.26 (21%), PULL_UP +0.09 (33%), PNR +0.04 (45%), SPOT_UP +0.02 (40%), POST_UP -0.22 (77%), DRIVE -0.27 (88%). n_units: CUT 103, DRIVE/POST_UP/SPO [cut; read_family for the full text]", "auto_failure_mechanism": "B_powered_null (adequately powered null result)", "observed_failure_evidence": "No conditional pivot branch met the durability bar (empty durable_branches). DRIVE/POST_UP negative net swing is the durable aftershock finding, recorded here as the positive half of the same run.", "observed_sample_and_power": "52 series, 104 units"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF-APPM-011"}]}], "n_results": 4}

